text:
{
  "claims": [
    {
      "anchor": "enable AOF on the live server with CONFIG SET appendonly yes",
      "claim_text": "To switch from RDB to AOF, enable AOF on the live server with CONFIG SET appendonly yes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "entails"},
        {"sid": "P1.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 0 says enable AOF via CONFIG on live server first; Passage 1 gives the command."
    },
    {
      "anchor": "also update redis.conf",
      "claim_text": "You must also update redis.conf when enabling AOF.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 1 says update redis.conf and ensure it matches."
    },
    {
      "anchor": "otherwise the change is lost when the server restarts",
      "claim_text": "If you do not update redis.conf, the configuration changes are lost when the server restarts.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 1 states forgetting this step loses changes on restart."
    },
    {
      "anchor": "Redis automatically blocks incoming writes while it converts the dataset",
      "claim_text": "Redis automatically blocks incoming writes while converting the dataset from RDB to AOF.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage mentions blocking writes during conversion."
    },
    {
      "anchor": "wait until aof_rewrite_in_progress and aof_rewrite_scheduled are both 0",
      "claim_text": "Before restarting, wait until aof_rewrite_in_progress and aof_rewrite_scheduled are both 0.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "entails"},
        {"sid": "P2.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 2 says wait for AOF rewrite and watch both fields to be 0."
    },
    {
      "anchor": "On Redis 7.0 or later",
      "claim_text": "On Redis 7.0 or later, an AOF-only instance can be backed up.",
      "kind": "version",
      "sure": true,
      "evidence": [
        {"sid": "P4.S0", "rel": "entails"},
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "7.0", "op": ">=", "right": "7.0.0"},
      "reasoning": "Passage 4 says AOF-only backups possible and since 7.0.0 AOF split into files."
    },
    {
      "anchor": "copying the files in the directory set by the appendfilename option",
      "claim_text": "On Redis 7.0 or later, back up by copying files in the directory set by the appendfilename option.",
      "kind": "direct",
      "sure": false,
      "evidence": [
        {"sid": "P4.S1", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage says directory determined by appenddirname, not appendfilename."
    },
    {
      "anchor": "copying them while a rewrite is running is safe",
      "claim_text": "Copying AOF files while a rewrite is running is safe.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S3", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage 4 says doing so during rewrite might yield invalid backup."
    },
    {
      "anchor": "set auto-aof-rewrite-percentage to 0, which turns off automatic rewrites",
      "claim_text": "Setting auto-aof-rewrite-percentage to 0 turns off automatic rewrites.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P5.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 5 says turn off automatic rewrites with that config."
    },
    {
      "anchor": "If you take hard links to those files, you can re-enable rewrites before the copy finishes",
      "claim_text": "If you take hard links to the AOF files, you can re-enable rewrites before the copy finishes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S0", "rel": "entails"},
        {"sid": "P6.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 6 says create hard links then re-enable rewrites, then copy hardlinks."
    },
    {
      "anchor": "because Redis only appends to files in that directory or completely replaces them",
      "claim_text": "Redis only appends to files in the appenddirname directory or completely replaces them.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 6 states this guarantee."
    },
    {
      "anchor": "On Redis 6.0, backing up the AOF is as simple as copying the aof file",
      "claim_text": "On Redis 6.0, backing up the AOF is as simple as copying the aof file.",
      "kind": "version",
      "sure": true,
      "evidence": [
        {"sid": "P7.S0", "rel": "entails"}
      ],
      "check": {"kind": "version", "left": "6.0", "op": "<", "right": "7.0.0"},
      "reasoning": "Passage 7 says prior to 7.0.0 copying aof file suffices; 6.0 is prior."
    },
    {
      "anchor": "Redis can still load the copy even if it lacks the final part",
      "claim_text": "Redis can still load a copied AOF file even if it lacks the final part.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 7 says file may lack final part but Redis can load it."
    }
  ]
}
